<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>圆的周长 - 一年级数学课件</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: "Microsoft YaHei", "PingFang SC", sans-serif;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            min-height: 100vh;
            color: #333;
            overflow-x: hidden;
        }

        /* ===== 顶部标题栏 ===== */
        .header {
            background: linear-gradient(90deg, #ff6b6b, #ffa726, #ffee58, #66bb6a, #42a5f5, #ab47bc);
            padding: 20px 0;
            text-align: center;
            box-shadow: 0 4px 15px rgba(0,0,0,0.2);
            position: sticky;
            top: 0;
            z-index: 100;
        }

        .header h1 {
            font-size: 2.2rem;
            color: #fff;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
            letter-spacing: 4px;
        }

        .header .subtitle {
            font-size: 1rem;
            color: rgba(255,255,255,0.9);
            margin-top: 6px;
        }

        /* ===== 导航栏 ===== */
        .nav-bar {
            display: flex;
            justify-content: center;
            gap: 15px;
            padding: 15px;
            background: rgba(255,255,255,0.15);
            backdrop-filter: blur(5px);
        }

        .nav-btn {
            padding: 10px 28px;
            border: none;
            border-radius: 30px;
            font-size: 1.1rem;
            font-weight: bold;
            cursor: pointer;
            transition: all 0.3s;
            color: #fff;
            background: rgba(255,255,255,0.2);
            border: 2px solid rgba(255,255,255,0.4);
        }

        .nav-btn:hover, .nav-btn.active {
            background: #fff;
            color: #764ba2;
            transform: scale(1.08);
            box-shadow: 0 4px 15px rgba(0,0,0,0.2);
        }

        /* ===== 通用容器 ===== */
        .container {
            max-width: 1000px;
            margin: 0 auto;
            padding: 20px;
        }

        section {
            display: none;
            animation: fadeIn 0.5s ease;
        }

        section.visible {
            display: block;
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .card {
            background: #fff;
            border-radius: 20px;
            padding: 30px;
            margin-bottom: 25px;
            box-shadow: 0 8px 30px rgba(0,0,0,0.12);
            transition: transform 0.3s;
        }

        .card:hover {
            transform: translateY(-3px);
        }

        .card h2 {
            font-size: 1.6rem;
            color: #5b3cc4;
            margin-bottom: 15px;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .card h2 .icon {
            font-size: 1.8rem;
        }

        .card p, .card li {
            font-size: 1.15rem;
            line-height: 2;
            color: #444;
        }

        /* ===== 概念讲解模块 ===== */
        .concept-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 20px;
            margin-top: 15px;
        }

        .concept-item {
            background: linear-gradient(135deg, #e8f5e9, #c8e6c9);
            border-radius: 15px;
            padding: 20px;
            text-align: center;
            border: 3px solid #66bb6a;
            transition: transform 0.3s;
        }

        .concept-item:hover {
            transform: scale(1.03);
        }

        .concept-item.circumference {
            background: linear-gradient(135deg, #fff3e0, #ffe0b2);
            border-color: #ffa726;
        }

        .concept-item.pi {
            background: linear-gradient(135deg, #fce4ec, #f8bbd0);
            border-color: #ec407a;
        }

        .concept-item.formula {
            background: linear-gradient(135deg, #e3f2fd, #bbdefb);
            border-color: #42a5f5;
        }

        .concept-item h3 {
            font-size: 1.3rem;
            margin-bottom: 10px;
        }

        .concept-item .big-text {
            font-size: 2rem;
            font-weight: bold;
            color: #333;
            margin: 10px 0;
        }

        .highlight-box {
            background: linear-gradient(135deg, #fff9c4, #fff176);
            border: 3px dashed #ffa726;
            border-radius: 15px;
            padding: 20px;
            margin-top: 20px;
            text-align: center;
        }

        .highlight-box .formula-big {
            font-size: 2.5rem;
            font-weight: bold;
            color: #e65100;
            margin: 10px 0;
            font-family: "Georgia", serif;
        }

        .step-list {
            list-style: none;
            padding: 0;
            margin-top: 15px;
        }

        .step-list li {
            background: #f3e5f5;
            margin: 8px 0;
            padding: 12px 18px;
            border-radius: 12px;
            border-left: 5px solid #ab47bc;
            font-size: 1.1rem;
        }

        .step-list li .step-num {
            display: inline-block;
            width: 30px;
            height: 30px;
            background: #ab47bc;
            color: #fff;
            border-radius: 50%;
            text-align: center;
            line-height: 30px;
            font-weight: bold;
            margin-right: 10px;
        }

        /* ===== 图形演示模块 ===== */
        .demo-area {
            text-align: center;
            position: relative;
        }

        .svg-container {
            display: flex;
            justify-content: center;
            align-items: center;
            gap: 40px;
            flex-wrap: wrap;
            margin: 20px 0;
        }

        .circle-demo {
            position: relative;
        }

        .circle-demo label {
            display: block;
            font-size: 1rem;
            font-weight: bold;
            color: #555;
            margin-bottom: 8px;
        }

        .controls-row {
            display: flex;
            justify-content: center;
            gap: 20px;
            flex-wrap: wrap;
            margin: 20px 0;
        }

        .control-group {
            background: #e8eaf6;
            border-radius: 15px;
            padding: 15px 25px;
            text-align: center;
        }

        .control-group label {
            font-weight: bold;
            color: #3949ab;
            display: block;
            margin-bottom: 8px;
        }

        .slider-row {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        input[type="range"] {
            width: 180px;
            height: 8px;
            -webkit-appearance: none;
            background: linear-gradient(90deg, #42a5f5, #7c4dff);
            border-radius: 5px;
            outline: none;
        }

        input[type="range"]::-webkit-slider-thumb {
            -webkit-appearance: none;
            width: 24px;
            height: 24px;
            background: #ff7043;
            border-radius: 50%;
            cursor: pointer;
            box-shadow: 0 2px 6px rgba(0,0,0,0.3);
        }

        .value-display {
            font-size: 1.4rem;
            font-weight: bold;
            color: #e65100;
            min-width: 50px;
        }

        .result-box {
            background: linear-gradient(135deg, #e8f5e9, #a5d6a7);
            border: 3px solid #43a047;
            border-radius: 15px;
            padding: 20px;
            margin-top: 15px;
            font-size: 1.3rem;
        }

        .result-box .result-value {
            font-size: 2rem;
            font-weight: bold;
            color: #2e7d32;
        }

        .animate-btn {
            background: linear-gradient(135deg, #ff6b6b, #ee5a24);
            color: #fff;
            border: none;
            border-radius: 30px;
            padding: 12px 35px;
            font-size: 1.2rem;
            font-weight: bold;
            cursor: pointer;
            margin-top: 15px;
            transition: all 0.3s;
            box-shadow: 0 4px 15px rgba(238, 90, 36, 0.4);
        }

        .animate-btn:hover {
            transform: scale(1.08);
            box-shadow: 0 6px 20px rgba(238, 90, 36, 0.6);
        }

        /* ===== 练习测试模块 ===== */
        .quiz-card {
            background: #fff;
            border-radius: 20px;
            padding: 25px;
            margin-bottom: 20px;
            border: 3px solid #e0e0e0;
            transition: all 0.3s;
        }

        .quiz-card.correct {
            border-color: #43a047;
            background: #e8f5e9;
        }

        .quiz-card.wrong {
            border-color: #e53935;
            background: #ffebee;
        }

        .quiz-card h3 {
            font-size: 1.2rem;
            color: #5b3cc4;
            margin-bottom: 12px;
        }

        .quiz-card .question-text {
            font-size: 1.15rem;
            color: #333;
            margin-bottom: 15px;
            line-height: 1.8;
        }

        .quiz-card .question-text .q-num {
            display: inline-block;
            background: #7c4dff;
            color: #fff;
            width: 28px;
            height: 28px;
            border-radius: 50%;
            text-align: center;
            line-height: 28px;
            font-size: 0.95rem;
            font-weight: bold;
            margin-right: 8px;
        }

        .options {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 10px;
        }

        .option-btn {
            padding: 12px 18px;
            border: 2px solid #bbdefb;
            border-radius: 12px;
            background: #e3f2fd;
            font-size: 1.1rem;
            cursor: pointer;
            transition: all 0.3s;
            text-align: center;
        }

        .option-btn:hover {
            background: #bbdefb;
            border-color: #42a5f5;
            transform: scale(1.03);
        }

        .option-btn.selected {
            background: #42a5f5;
            color: #fff;
            border-color: #1565c0;
        }

        .option-btn.correct-answer {
            background: #43a047;
            color: #fff;
            border-color: #2e7d32;
        }

        .option-btn.wrong-answer {
            background: #e53935;
            color: #fff;
            border-color: #b71c1c;
        }

        .fill-input {
            width: 120px;
            padding: 8px 15px;
            font-size: 1.2rem;
            border: 3px solid #42a5f5;
            border-radius: 10px;
            text-align: center;
            outline: none;
            transition: border-color 0.3s;
        }

        .fill-input:focus {
            border-color: #7c4dff;
            box-shadow: 0 0 10px rgba(124, 77, 255, 0.3);
        }

        .feedback {
            margin-top: 10px;
            padding: 10px 15px;
            border-radius: 10px;
            font-weight: bold;
            font-size: 1.05rem;
            display: none;
        }

        .feedback.show {
            display: block;
            animation: fadeIn 0.3s ease;
        }

        .feedback.correct {
            background: #c8e6c9;
            color: #2e7d32;
        }

        .feedback.wrong {
            background: #ffcdd2;
            color: #c62828;
        }

        .check-btn {
            background: linear-gradient(135deg, #7c4dff, #536dfe);
            color: #fff;
            border: none;
            border-radius: 25px;
            padding: 10px 30px;
            font-size: 1.1rem;
            font-weight: bold;
            cursor: pointer;
            margin-top: 12px;
            transition: all 0.3s;
        }

        .check-btn:hover {
            transform: scale(1.06);
            box-shadow: 0 4px 15px rgba(92, 107, 254, 0.5);
        }

        .score-board {
            background: linear-gradient(135deg, #fff9c4, #fff176);
            border: 3px solid #ffc107;
            border-radius: 20px;
            padding: 25px;
            text-align: center;
            margin-top: 20px;
        }

        .score-board h3 {
            font-size: 1.5rem;
            color: #e65100;
        }

        .score-board .score {
            font-size: 3rem;
            font-weight: bold;
            color: #d32f2f;
            margin: 10px 0;
        }

        .score-board .score-text {
            font-size: 1.2rem;
            color: #555;
        }

        .reset-btn {
            background: linear-gradient(135deg, #ff7043, #f4511e);
            color: #fff;
            border: none;
            border-radius: 25px;
            padding: 12px 35px;
            font-size: 1.15rem;
            font-weight: bold;
            cursor: pointer;
            margin-top: 15px;
            transition: all 0.3s;
        }

        .reset-btn:hover {
            transform: scale(1.08);
        }

        /* ===== 页脚 ===== */
        .footer {
            text-align: center;
            padding: 20px;
            color: rgba(255,255,255,0.7);
            font-size: 0.95rem;
        }

        /* ===== 动画圆周 ===== */
        @keyframes dashDraw {
            to {
                stroke-dashoffset: 0;
            }
        }

        @keyframes pulse {
            0%, 100% { transform: scale(1); }
            50% { transform: scale(1.05); }
        }

        .pulse-anim {
            animation: pulse 2s infinite;
        }

        /* ===== 响应式 ===== */
        @media (max-width: 768px) {
            .concept-grid {
                grid-template-columns: 1fr;
            }
            .header h1 {
                font-size: 1.6rem;
            }
            .options {
                grid-template-columns: 1fr;
            }
            .svg-container {
                gap: 15px;
            }
        }
    </style>
</head>
<body>

